def key(title):
    s=title.lower().replace('ß','ss');s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode()
    return re.sub(r'[^a-z0-9]+','-',s).strip('-')
TIMES={
'Öl- und Filterwechsel':(45,30,60,'https://www.boschcarservice.com/de/de/werkstattleistungen/oel-und-filterwechsel/'),
'Kleine Inspektion':(105,90,120,'https://www.boschcarservice.com/de/de/werkstattleistungen/inspektion/auto-inspektion/'),
'Große Inspektion':(210,180,240,'https://www.boschcarservice.com/de/de/werkstattleistungen/inspektion/auto-inspektion/'),
'Saisonaler Räderwechsel':(25,25,25,'https://www.autoservicekoehler.de/aktionen/'),
'Achsvermessung mit Einstellung':(75,75,75,'https://www.autoservicekoehler.de/aktionen/')}
rows=[]
for category,titles in GROUPS.items():
    for title in titles.split('|'):
        k=key(title); tm=TIMES.get(title)
        synonyms=[]
        if title=='Saisonaler Räderwechsel': synonyms=['Reifenwechsel','Sommerreifen','Winterreifen']
        if title=='Öl- und Filterwechsel': synonyms=['Ölwechsel','Ölservice']
        if title=='Fehlerspeicher auslesen': synonyms=['OBD','Diagnose','Fehlercodes']
        includes={'Kleine Inspektion':['ol-und-filterwechsel'], 'Große Inspektion':['kleine-inspektion','ol-und-filterwechsel'], 'Bremsscheiben und Beläge erneuern':['bremsbelage-erneuern'], 'Räderwechsel mit Einlagerung':['saisonaler-raderwechsel','reifen-einlagern']}.get(title,[])
        rows.append(dict(key=k,title=title,category=category,description=f'{title}: Umfang und Fahrzeugausführung vor Arbeitsbeginn prüfen.',steps=[f'{title} nach fahrzeugspezifischen Vorgaben durchführen','Ergebnis und gegebenenfalls weitere Befunde dokumentieren'],unit='Leistung',vehicle_classes=['car','van'],synonyms=synonyms,includes=includes,minutes=tm[0] if tm else None,time_min=tm[1] if tm else None,time_max=tm[2] if tm else None,time_source=tm[3] if tm else '',time_kind='research' if tm else 'unknown',favorite=bool(tm),position=len(rows),archived=False,own_price=None))
assert len(rows)>=250 and len({r['key'] for r in rows})==len(rows)
(ROOT/'lib/Data/services.json').write_text(json.dumps({'version':'2026-10-05.1','services':rows},ensure_ascii=False,indent=2)+'\n')
print(f'{len(rows)} distinct services in {len(GROUPS)} categories')
